fun isAcknowledged(entry: LogEntry, waitedMs: Long): Boolean {
    fun has(f: Node) = (confirmed[f.name] ?: 0) >= entry.position
    return when (mode) {
        Mode.Async -> true                                       // the leader's disk is enough
        is Mode.Sync -> followers.count(::has) >= mode.followers
        is Mode.SemiSync -> when {
            !semiSyncOn -> true                                  // already fallen back
            followers.any(::has) -> true
            waitedMs >= mode.timeoutMs -> { semiSyncOn = false; true }   // silent fallback
            else -> false
        }
    }
}
